<!DOCTYPE html>
<html lang="hu">
<head>
<meta charset="utf-8">
<meta http-equiv="x-ua-compatible" content="IE=edge">
<meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0">
<title>White-Label PSP Platform</title>
<meta name="color-scheme" content="light dark">
<link rel="preconnect" href="/">
<style>
:root{--bg:#0b0c10;--fg:#e5e7eb;--muted:#9ca3af;--primary:#06b6d4;--primary-2:#22d3ee;--accent:#22c55e;--danger:#ef4444;--card:#111827;--border:#1f2937;--shadow:rgba(0,0,0,.4)}
*{box-sizing:border-box}html,body{margin:0;padding:0;height:100%}body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Inter,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--fg)}
a{text-decoration:none;color:inherit}
input,button,select,textarea{font:inherit;color:inherit}
.container{max-width:1200px;margin:0 auto;padding:16px}
.nav{display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border);position:sticky;top:0;background:color-mix(in oklab,var(--bg) 92%, black 8%);backdrop-filter:saturate(1.2) blur(6px);z-index:10}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.3px}
.brand-badge{display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:linear-gradient(135deg,var(--primary),var(--primary-2))}
.navlinks{display:flex;gap:10px;flex-wrap:wrap}
.navlink{padding:8px 10px;border:1px solid var(--border);border-radius:8px;color:var(--muted)}
.navlink.active{color:var(--fg);border-color:color-mix(in oklab,var(--primary) 60%, var(--border))}
.spacer{flex:1}
.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 14px;border-radius:10px;border:1px solid var(--border);background:linear-gradient(0deg,color-mix(in oklab,var(--card) 85%, black 15%),color-mix(in oklab,var(--card) 80%, black 20%));box-shadow:0 10px 24px -18px var(--shadow)}
.btn.primary{border-color:color-mix(in oklab,var(--primary) 35%, var(--border));background:linear-gradient(180deg,color-mix(in oklab,var(--primary) 18%, var(--card)),color-mix(in oklab,var(--primary) 8%, var(--card)))}
.btn.danger{border-color:color-mix(in oklab,var(--danger) 35%, var(--border));background:linear-gradient(180deg,color-mix(in oklab,var(--danger) 14%, var(--card)),color-mix(in oklab,var(--danger) 6%, var(--card)))}
.grid{display:grid;gap:16px}
.grid.cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.grid.cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:1024px){.grid.cols-3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:720px){.grid.cols-3,.grid.cols-2{grid-template-columns:1fr}}
.card{border:1px solid var(--border);border-radius:14px;background:linear-gradient(180deg,color-mix(in oklab,var(--card) 86%, black 14%),color-mix(in oklab,var(--card) 80%, black 20%));box-shadow:0 10px 28px -16px var(--shadow)}
