</head>
<body>
<div id="app"></div>
<script>
const apiBase = "/api/v1";
const s = (k,d=null)=>{try{const v=localStorage.getItem(k);return v===null?d:JSON.parse(v)}catch{return d}};
const w = (k,v)=>localStorage.setItem(k,JSON.stringify(v));
const q = async (url, opts={})=>{
  const headers = Object.assign({"Content-Type":"application/json"}, opts.headers||{});
  const token = s("auth_token", null);
  if(token) headers["Authorization"] = "Bearer " + token;
  const res = await fetch(url, Object.assign({}, opts, {headers}));
  if(!res.ok){
    const text = await res.text();
    throw new Error(text||("HTTP "+res.status));
  }
  const ct = res.headers.get("content-type")||"";
  if(ct.includes("application/json")) return res.json();
  return res.text();
};
const h = (tag, props={}, ...children)=>{
  const el = document.createElement(tag);
  for(const k in props){
    const v = props[k];
    if(k==="class") el.className = v;
    else if(k.startsWith("on") && typeof v === "function") el.addEventListener(k.slice(2).toLowerCase(), v, {passive:true});
    else if(v!==null && v!==undefined) el.setAttribute(k, v);
  }
  children.flat().forEach(c=>{
    if(c===null||c===undefined) return;
    if(typeof c==="string"||typeof c==="number") el.appendChild(document.createTextNode(String(c)));
    else el.appendChild(c);
  });
  return el;
};
const icon = (ch)=>h("span",{ariaHidden:"true",style:"display:inline-grid;place-items:center;width:1.15em;height:1.15em;border-radius:6px;background:linear-gradient(135deg,var(--primary),var(--primary-2));color:#05232a;font-weight:800"},ch);
const state = {
  route: location.hash.replace(/^#*/,"") || "/login",
  user: s("auth_user", null),
  loading: false,
  metrics: null,
  txns: [],
};
const navigate = (path)=>{
  if(path===state.route) return;
  state.route = path;
  location.hash = path;
  render();
};
window.addEventListener("hashchange", ()=>{state.route = location.hash.replace(/^#*/,"") || "/login"; render();});
const requireAuth = ()=>{
  if(!s("auth_token", null)){navigate("/login"); return false}
  return true;
};
const logout = ()=>{
  localStorage.removeItem("auth_token");
  localStorage.removeItem("auth_user");
  state.user = null;
  navigate("/login");
};
const Nav = ()=>{
  const current = state.route;
  const link = (to,label)=>h("a",{href:"#"+to,class:"navlink"+(current===to?" active":"")},label);
  return h("div",{class:"nav"},
    h("div",{class:"brand"}, h("span",{class:"brand-badge"}, "WL"), h("span","White-Label PSP")),
    h("div",{class:"navlinks"},
      link("/dashboard","Vezérlőpult"),
      link("/transactions","Tranzakciók"),
      link("/merchants","Kereskedő felvétele"),
      link("/psd2","PSD2"),
      link("/sepa","SEPA"),
      link("/settlements","Elszámolások"),
      link("/analytics","Analitika"),
      link("/settings","Beállítások")
    ),
    h("div",{class:"spacer"}),
    state.user ? h("button",{class:"btn danger",onClick:logout}, icon("⎋"), "Kilépés") : h("a",{href:"#/login",class:"btn"}, icon("→"), "Belépés")
  );
};
const SectionCard = (title, right=null, body=[])=>{
  return h("div",{class:"card"},
    h("div",{class:"head"}, h("div",null,title), right),
    h("div",{class:"body"}, body)
  );
};
const LoginView = ()=>{
  const formId = "loginForm";
  const onSubmit = async (e)=>{
    e.preventDefault();
    const fd = new FormData(e.target);
    const email = (fd.get("email")||"").toString().trim();
    const password = (fd.get("password")||"").toString();
    if(!email || !password) return;
    try{
      state.loading = true; render();
      const res = await q(apiBase+"/auth/login",{method:"POST",body:JSON.stringify({email,password})});
      w("auth_token", res.access_token);
      w("auth_user", res.user);
      state.user = res.user;
      navigate("/dashboard");
    }catch(err){
      alert("Bejelentkezés sikertelen: "+err.message);
    }finally{
      state.loading = false; render();
    }
  };
  return h("div",{class:"container"},
    h("div",{class:"grid cols-2"},
      SectionCard("Üdvözlünk", null, [
        h("p",null,"Kérjük jelentkezz be a folytatáshoz."),
        h("ul",null,
          h("li",null,"Erős jelszavakat használj."),
          h("li",null,"A munkamenet automatikus lejárattal védett."),
          h("li",null,"Az API kérések JWT és mTLS ellenőrzött csatornán futnak.")
        )
      ]),
      SectionCard("Bejelentkezés", null, [
        h("form",{id:formId,onSubmit},
          h("div",{class:"row"},
            h("label",null,"Email"),
            h("input",{class:"input",name:"email",type:"email",required:"true",autocomplete:"username"})
          ),
          h("div",{class:"row"},
            h("label",null,"Jelszó"),
            h("input",{class:"input",name:"password",type:"password",required:"true",autocomplete:"current-password"})
          ),
          h("div",{style:"height:8px"}),
          h("button",{class:"btn primary",type:"submit",disabled:state.loading? "true": null}, state.loading? "Folyamatban..." : "Belépés")
        ),
        h("div",{class:"helper"},"Nincs fiókod? Kérd az adminisztrátortól a hozzáférést.")
      ])
    )
  );
};
const number = (v)=>new Intl.NumberFormat("hu-HU").format(Number(v||0));
const money = (v,c="EUR")=>new Intl.NumberFormat("hu-HU",{style:"currency",currency:c}).format(Number(v||0));
const DashboardView = ()=>{
  const load = async ()=>{
    try{
      state.loading = true; render();
      const data = await q(apiBase+"/metrics");
      state.metrics = data;
    }catch(err){
      alert("Metrikák betöltése sikertelen: "+err.message);
    }finally{
      state.loading = false; render();
    }
  };
  if(!state.metrics && !state.loading) load();
  const m = state.metrics || {
    total_volume_today: 0,
    total_transactions_today: 0,
    success_rate: 0,
    active_merchants: 0,
    pending_settlements: 0,
    average_transaction_value: 0,
    volume_trend: [],
    transaction_trend: []
  };
  const Stats = h("div",{class:"grid cols-3"},
    SectionCard("Napi forgalom", h("span",{class:"badge"},icon("€"), "Ma"), [
      h("div",{class:"stat"}, h("div",{class:"k"},"Összeg"), h("div",{class:"v"}, money(m.total_volume_today,"EUR"))),
      h("div",{class:"stat"}, h("div",{class:"k"},"Átlagos érték"), h("div",{class:"v"}, money(m.average_transaction_value,"EUR")))
    ]),
    SectionCard("Tranzakciók", h("span",{class:"badge"},icon("≡"), "Ma"), [
      h("div",{class:"stat"}, h("div",{class:"k"},"Darab"), h("div",{class:"v"}, number(m.total_transactions_today))),
      h("div",{class:"stat"}, h("div",{class:"k"},"Sikerarány"), h("div",{class:"v"}, number((m.success_rate||0)*100)+"%"))
    ]),
    SectionCard("Kereskedők", h("span",{class:"badge"},icon("✓"), "Aktív"), [
      h("div",{class:"stat"}, h("div",{class:"k"},"Aktív kereskedők"), h("div",{class:"v"}, number(m.active_merchants))),
      h("div",{class:"stat"}, h("div",{class:"k"},"Függő elszámolások"), h("div",{class:"v"}, number(m.pending_settlements)))
    ])
  );
  const TrendCard = SectionCard("Trendek", h("span",{class:"badge"},icon("↗"), "7 nap"), [
    h("canvas",{id:"chart1",class:"chart",width:"1200",height:"220"})
  ]);
  setTimeout(()=>{
    const c1 = document.getElementById("chart1");
    if(!c1 || c1.dataset.rendered==="1") return;
    c1.dataset.rendered="1";
    const ctx = c1.getContext("2d");
    const data = (m.volume_trend||[]).map(x=>Number(x.amount||0));
    const max = Math.max(1,...data);
    ctx.clearRect(0,0,c1.width,c1.height);
    ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--primary') || "#06b6d4";
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((v,i)=>{
      const x = (i/(Math.max(1,data.length-1)))*(c1.width-20)+10;
      const y = c1.height-10 - (v/max)*(c1.height-30);
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.stroke();
  },0);
  return h("div",{class:"container"}, Stats, TrendCard);
};
const TransactionsView = ()=>{
  const load = async ()=>{
    try{
      state.loading = true; render();
      const list = await q(apiBase+"/transactions?limit=50");
      state.txns = list||[];
    }catch(err){
      alert("Tranzakciók betöltése sikertelen: "+err.message);
    }finally{
      state.loading = false; render();
    }
  };
  if(state.txns.length===0 && !state.loading) load();
  return h("div",{class:"container"},
    SectionCard("Tranzakciók", h("a",{href:"#/transactions",class:"badge"}, "Frissítés"), [
      h("div",{style:"overflow:auto"},
        h("table",{class:"table"},
          h("thead",null,
            h("tr",null,
              h("th",null,"ID"),
              h("th",null,"Kereskedő"),
              h("th",null,"Összeg"),
              h("th",null,"Pénznem"),
              h("th",null,"Típus"),
              h("th",null,"Állapot"),
              h("th",null,"Létrehozva")
            )
          ),
          h("tbody",null,
            state.txns.map(t=>h("tr",null,
              h("td",null,t.transaction_id||t.id||""),
              h("td",null,t.merchant_id||""),
              h("td",null,money(t.amount||0,t.currency||"EUR")),
              h("td",null,t.currency||"EUR"),
              h("td",null,t.transaction_type||t.type||""),
              h("td",null,t.status||""),
              h("td",null,(t.created_at||"").toString().replace("T"," ").replace("Z",""))
            ))
          )
        )
      )
    ])
  );
};
const MerchantsView = ()=>{
  const onSubmit = async (e)=>{
    e.preventDefault();
    const fd = new FormData(e.target);
    const payload = {
      legal_name: (fd.get("legal_name")||"").toString(),
      trade_name: (fd.get("trade_name")||"").toString(),
      registration_number: (fd.get("registration_number")||"").toString(),
      tax_id: (fd.get("tax_id")||"").toString(),
      legal_form: (fd.get("legal_form")||"").toString(),
      country: (fd.get("country")||"HU").toString(),
      address_line1: (fd.get("address_line1")||"").toString(),
      address_line2: (fd.get("address_line2")||"").toString() || null,
      city: (fd.get("city")||"").toString(),
      postal_code: (fd.get("postal_code")||"").toString(),
      email: (fd.get("email")||"").toString(),
      phone: (fd.get("phone")||"").toString(),
      business_category: (fd.get("business_category")||"").toString(),
      expected_monthly_volume: Number(fd.get("expected_monthly_volume")||0),
      website_url: ((fd.get("website_url")||"").toString()||null),
      bank_account_iban: (fd.get("bank_account_iban")||"").toString(),
      bank_account_bic: (fd.get("bank_account_bic")||"").toString(),
      authorized_person_name: (fd.get("authorized_person_name")||"").toString(),
      authorized_person_id: (fd.get("authorized_person_id")||"").toString()
    };
    try{
      state.loading = true; render();
      const res = await q(apiBase+"/merchants/onboard",{method:"POST",body:JSON.stringify(payload)});
      alert("Kereskedő regisztrálva: "+(res.merchant_id||""));
    }catch(err){
      alert("Hiba: "+err.message);
    }finally{
      state.loading = false; render();
    }
  };
  return h("div",{class:"container"},
    SectionCard("Kereskedő felvétele", null, [
      h("form",{onSubmit},
        h("div",{class:"row cols-2"},
          h("div",null,h("label",null,"Jogi név"), h("input",{class:"input",name:"legal_name",required:"true"})),
          h("div",null,h("label",null,"Kereskedelmi név"), h("input",{class:"input",name:"trade_name",required:"true"})),
          h("div",null,h("label",null,"Cégjegyzékszám"), h("input",{class:"input",name:"registration_number",required:"true"})),
          h("div",null,h("label",null,"Adószám"), h("input",{class:"input",name:"tax_id",required:"true"})),
          h("div",null,h("label",null,"Jogi forma"), h("input",{class:"input",name:"legal_form"})),
          h("div",null,h("label",null,"Ország"), h("input",{class:"input",name:"country",value:"HU"})),
          h("div",null,h("label",null,"Cím 1"), h("input",{class:"input",name:"address_line1",required:"true"})),
          h("div",null,h("label",null,"Cím 2"), h("input",{class:"input",name:"address_line2"})),
          h("div",null,h("label",null,"Város"), h("input",{class:"input",name:"city",required:"true"})),
          h("div",null,h("label",null,"Irányítószám"), h("input",{class:"input",name:"postal_code",required:"true"})),
          h("div",null,h("label",null,"Email"), h("input",{class:"input",type:"email",name:"email",required:"true"})),
          h("div",null,h("label",null,"Telefon"), h("input",{class:"input",name:"phone",required:"true"})),
          h("div",null,h("label",null,"Tevékenység"), h("input",{class:"input",name:"business_category"})),
          h("div",null,h("label",null,"Havi forgalom (EUR)"), h("input",{class:"input",type:"number",name:"expected_monthly_volume",step:"0.01"})),
          h("div",null,h("label",null,"Weboldal"), h("input",{class:"input",name:"website_url"})),
          h("div",null,h("label",null,"IBAN"), h("input",{class:"input",name:"bank_account_iban",required:"true"})),
          h("div",null,h("label",null,"BIC"), h("input",{class:"input",name:"bank_account_bic"})),
          h("div",null,h("label",null,"Felhatalmazott neve"), h("input",{class:"input",name:"authorized_person_name",required:"true"})),
          h("div",null,h("label",null,"Felhatalmazott azonosítója"), h("input",{class:"input",name:"authorized_person_id",required:"true"}))
        ),
        h("div",{style:"height:8px"}),
        h("button",{class:"btn primary",type:"submit"}, "Mentés")
      )
    ])
  );
};
const PSD2View = ()=>{
  const accountsId = "accOut";
  const tokenInput = "tokIn";
  const load = async ()=>{
    try{
      const token = document.getElementById(tokenInput).value.trim();
      if(!token){alert("Hiányzik a Bearer token");return}
      const data = await q(apiBase+"/psd2/accounts",{headers:{Authorization:"Bearer "+token}});
      const el = document.getElementById(accountsId);
      el.textContent = JSON.stringify(data,null,2);
    }catch(err){
      alert("PSD2 hiba: "+err.message);
    }
  };
  return h("div",{class:"container"},
    SectionCard("PSD2 számlák", null, [
      h("div",{class:"row"},
        h("label",null,"Bearer token"),
        h("input",{class:"input",id:tokenInput,placeholder:"Bearer ..."})
      ),
      h("div",{style:"height:8px"}),
      h("button",{class:"btn primary",onClick:load},"Lekérdezés"),
      h("pre",{id:accountsId,style:"white-space:pre-wrap;overflow:auto;min-height:80px;border:1px solid var(--border);border-radius:10px;padding:12px;marginTop:'8px' },"")
    ])
  );
};
const SEPAView = ()=>{
  const onSubmit = async (e)=>{
    e.preventDefault();
    const fd = new FormData(e.target);
    const debtor = (fd.get("debtor_name")||"").toString();
    const debtorIban = (fd.get("debtor_iban")||"").toString();
    const debtorBic = (fd.get("debtor_bic")||"").toString();
    const execution_date = (fd.get("execution_date")||"").toString() || null;
    const txCount = Number(fd.get("tx_count")||1);
    const transactions = [];
    for(let i=0;i<txCount;i++){
      transactions.push({
        creditor_name: (fd.get("creditor_name_"+i)||"").toString(),
        creditor_iban: (fd.get("creditor_iban_"+i)||"").toString(),
        creditor_bic: (fd.get("creditor_bic_"+i)||"").toString(),
        amount: Number(fd.get("amount_"+i)||0),
        currency: "EUR",
        description: (fd.get("description_"+i)||"").toString()
      });
    }
    const payload = {debtor_name:debtor, debtor_iban:debtorIban, debtor_bic:debtorBic, transactions, execution_date};
    try{
      const res = await q(apiBase+"/sepa/credit-transfer",{method:"POST",body:JSON.stringify(payload)});
      alert("SEPA XML létrehozva");
      const a = document.createElement("a");
      const blob = new Blob([res.xml||res],{type:"application/xml"});
      a.href = URL.createObjectURL(blob);
      a.download = "sepa.xml";
      a.click();
      URL.revokeObjectURL(a.href);
    }catch(err){
      alert("SEPA hiba: "+err.message);
    }
  };
  const rows = [];
  const n = 2;
  for(let i=0;i<n;i++){
    rows.push(
      h("div",{class:"row cols-2"},
        h("div",null,h("label",null,"Kedvezményezett név"), h("input",{class:"input",name:"creditor_name_"+i})),
        h("div",null,h("label",null,"Kedvezményezett IBAN"), h("input",{class:"input",name:"creditor_iban_"+i})),
        h("div",null,h("label",null,"BIC"), h("input",{class:"input",name:"creditor_bic_"+i})),
        h("div",null,h("label",null,"Összeg (EUR)"), h("input",{class:"input",type:"number",step:"0.01",name:"amount_"+i})),
        h("div",null,h("label",null,"Közlemény"), h("input",{class:"input",name:"description_"+i}))
      )
    );
  }
  return h("div",{class:"container"},
    SectionCard("SEPA átutalás", null, [
      h("form",{onSubmit},
        h("div",{class:"row cols-2"},
          h("div",null,h("label",null,"Kibocsátó név"), h("input",{class:"input",name:"debtor_name"})),
          h("div",null,h("label",null,"Kibocsátó IBAN"), h("input",{class:"input",name:"debtor_iban"})),
          h("div",null,h("label",null,"Kibocsátó BIC"), h("input",{class:"input",name:"debtor_bic"})),
