        ),
        h("div",{style:"height:10px"}),
        ...rows,
        h("div",{style:"height:10px"}),
        h("button",{class:"btn primary",type:"submit"},"XML generálás")
      )
    ])
  );
};
const SettlementsView = ()=>{
