      h("p",null,"Idősorok, sikerarány, kártyatípus-eloszlás és csalás kockázat mutatók.")
    ])
  );
};
const SettingsView = ()=>{
  const onRotate = async ()=>{
    try{
      await q(apiBase+"/auth/rotate-keys",{method:"POST"});
      alert("Kulcsok megújítva");
    }catch(err){
      alert("Kulcs megújítás hiba: "+err.message);
    }
  };
  return h("div",{class:"container"},
    SectionCard("Beállítások", null, [
      h("button",{class:"btn primary",onClick:onRotate},"JWT kulcsok megújítása"),
      h("p",{class:"helper"},"Biztonságos kulcsmenedzsment és mTLS ellenőrzés.")
    ])
  );
};
const Guard = (view)=>{
  if(!requireAuth()) return LoginView();
  return view();
};
const App = ()=>{
  const r = state.route;
  let content;
  if(r==="/login") content = LoginView();
  else if(r==="/dashboard") content = Guard(DashboardView);
  else if(r==="/transactions") content = Guard(TransactionsView);
  else if(r==="/merchants") content = Guard(MerchantsView);
  else if(r==="/psd2") content = Guard(PSD2View);
  else if(r==="/sepa") content = Guard(SEPAView);
  else if(r==="/settlements") content = Guard(SettlementsView);
  else if(r==="/analytics") content = Guard(AnalyticsView);
  else if(r==="/settings") content = Guard(SettingsView);
  else content = LoginView();
  return h("div",null, Nav(), content, h("footer",null,"© ", new Date().getFullYear()," WL PSP"));
};
const render = ()=>{
  const root = document.getElementById("app");
  root.replaceChildren(App());
};
render();
</script>
</body>
</html>
