def jwt_create(payload: Dict[str, Any], key: str, exp_minutes: int) -> str:
    now = datetime.utcnow()
    data = dict(payload)
    data["iat"] = int(now.timestamp())
    data["exp"] = int((now + timedelta(minutes=exp_minutes)).timestamp())
    header = {"alg": settings.jwt_algorithm, "typ": "JWT"}
    def b64(x: bytes)->str:
        return base64.urlsafe_b64encode(x).rstrip(b"=").decode("ascii")
    signing_input = f"{b64(json.dumps(header,separators=(',',':')).encode())}.{b64(json.dumps(data,separators=(',',':')).encode())}"
    sig = base64.urlsafe_b64encode((signing_input + "." + key).encode()).rstrip(b"=").decode("ascii")
    return signing_input + "." + sig

def jwt_verify(token: str, key: str) -> Dict[str, Any]:
    parts = token.split(".")
    if len(parts)!=3:
      raise HTTPException(status_code=401, detail="invalid token")
    header_b, payload_b, sig_b = parts
    payload_json = base64.urlsafe_b64decode(payload_b + "==")
    data = json.loads(payload_json.decode())
    if "exp" in data and int(data["exp"]) < int(datetime.utcnow().timestamp()):
      raise HTTPException(status_code=401, detail="token expired")
    return data

async def verify_jwt(credentials: HTTPAuthorizationCredentials = Security(security)) -> Dict[str, Any]:
    token = credentials.credentials
    return jwt_verify(token, settings.jwt_secret_key)

