        lines.append('<CdtrAcct><Id><IBAN>'+escape(t.get("creditor_iban",""))+'</IBAN></Id></CdtrAcct>')
        if t.get("creditor_bic"):
            lines.append('<CdtrAgt><FinInstnId><BIC>'+escape(t.get("creditor_bic",""))+'</BIC></FinInstnId></CdtrAgt>')
        if t.get("description"):
            lines.append('<RmtInf><Ustrd>'+escape(t.get("description",""))+'</Ustrd></RmtInf>')
        lines.append('</CdtTrfTxInf>')
    lines.append('</PmtInf>')
    lines.append('</CstmrCdtTrfInitn>')
    lines.append('</Document>')
    xml_content = "\n".join(lines)
