const drawLine = (canvas, data, color)=>{
  const c = canvas;
  const ctx = c.getContext("2d");
  const vals = data.map(x=>Number(x||0));
  const max = Math.max(1,...vals);
  ctx.clearRect(0,0,c.width,c.height);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.beginPath();
  vals.forEach((v,i)=>{
    const x = (i/(Math.max(1,vals.length-1)))*(c.width-20)+10;
    const y = c.height-10 - (v/max)*(c.height-30);
    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  });
  ctx.stroke();
};
