engine = create_engine(settings.sqlite_url, connect_args={"check_same_thread": False} if settings.sqlite_url.startswith("sqlite") else {}, future=True)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True, index=True)
    email = Column(String(255), unique=True, index=True, nullable=False)
    name = Column(String(255), nullable=False)
    role = Column(String(64), nullable=False, default="admin")
    password_hash = Column(String(255), nullable=False)
    created_at = Column(DateTime, nullable=False, default=datetime.utcnow)
    __table_args__ = (Index("ix_users_email", "email"),)

class JwtKey(Base):
    __tablename__ = "jwt_keys"
    id = Column(Integer, primary_key=True, index=True)
    secret = Column(Text, nullable=False)
    created_at = Column(DateTime, nullable=False, default=datetime.utcnow)

class Merchant(Base):
    __tablename__ = "merchants"
    id = Column(String(32), primary_key=True)
    legal_name = Column(String(255), nullable=False)
    trade_name = Column(String(255), nullable=False)
    registration_number = Column(String(128), nullable=False)
    tax_id = Column(String(128), nullable=False)
    legal_form = Column(String(64), nullable=True)
    country = Column(String(2), nullable=False)
    address_line1 = Column(String(255), nullable=False)
    address_line2 = Column(String(255), nullable=True)
    city = Column(String(128), nullable=False)
    postal_code = Column(String(32), nullable=False)
    email = Column(String(255), nullable=False)
    phone = Column(String(64), nullable=False)
    business_category = Column(String(128), nullable=True)
    expected_monthly_volume = Column(Numeric(18,2), nullable=False, default=0)
    website_url = Column(String(255), nullable=True)
    bank_account_iban = Column(String(64), nullable=False)
    bank_account_bic = Column(String(64), nullable=True)
    authorized_person_name = Column(String(255), nullable=False)
    authorized_person_id = Column(String(128), nullable=False)
    status = Column(String(32), nullable=False, default="pending_verification")
    created_at = Column(DateTime, nullable=False, default=datetime.utcnow)

class Transaction(Base):
    __tablename__ = "transactions"
    id = Column(String(40), primary_key=True)
    merchant_id = Column(String(32), ForeignKey("merchants.id"), nullable=False)
    amount = Column(Numeric(18,2), nullable=False)
    currency = Column(String(3), nullable=False)
    transaction_type = Column(String(32), nullable=False)
    status = Column(String(32), nullable=False)
    created_at = Column(DateTime, nullable=False, default=datetime.utcnow)
    __table_args__ = (Index("ix_transactions_created", "created_at"),)

