class MetricsResponse(BaseModel):
    total_volume_today: Decimal
    total_transactions_today: int
    success_rate: float
    active_merchants: int
    pending_settlements: int
    average_transaction_value: Decimal
    volume_trend: List[Dict[str, Any]]
    transaction_trend: List[Dict[str, Any]]

security = HTTPBearer()

def get_db() -> Session:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

def now_utc() -> datetime:
    return datetime.utcnow()

def get_active_secret(db: Session) -> str:
    key = db.query(JwtKey).order_by(JwtKey.id.desc()).first()
    if not key:
        secret = secrets.token_urlsafe(48)
        key = JwtKey(secret=secret)
        db.add(key)
        db.commit()
        db.refresh(key)
    return key.secret

def rotate_secret(db: Session) -> str:
    secret = secrets.token_urlsafe(48)
    key = JwtKey(secret=secret)
    db.add(key)
    db.commit()
    return secret

def create_access_token(db: Session, subject: str, claims: Dict[str, Any]) -> str:
    iat = int(now_utc().timestamp())
    exp = int((now_utc() + timedelta(minutes=settings.jwt_exp_minutes)).timestamp())
    payload = {"sub": subject, "iat": iat, "exp": exp}
    payload.update(claims or {})
    secret = get_active_secret(db)
    token = jwt.encode(payload, secret, algorithm=settings.jwt_algorithm)
    return token

def verify_token(db: Session, token: str) -> Dict[str, Any]:
    secrets_to_try = []
    keys = db.query(JwtKey).order_by(JwtKey.id.desc()).limit(2).all()
    for k in keys:
        secrets_to_try.append(k.secret)
    last_exc = None
    for s in secrets_to_try:
        try:
            data = jwt.decode(token, s, algorithms=[settings.jwt_algorithm])
            return data
        except Exception as e:
            last_exc = e
            continue
    raise HTTPException(status_code=401, detail="invalid or expired token")

def auth_guard(credentials: HTTPAuthorizationCredentials = Depends(security), db: Session = Depends(get_db)) -> Dict[str, Any]:
    return verify_token(db, credentials.credentials)

def password_hash(p: str) -> str:
    return pwd_ctx.hash(p)

def password_verify(p: str, h: str) -> bool:
    return pwd_ctx.verify(p, h)

def ensure_admin(db: Session):
    user = db.query(User).filter(User.email == settings.admin_email).first()
    if not user:
        u = User(email=settings.admin_email, name="Administrator", role="admin", password_hash=password_hash(settings.admin_password))
        db.add(u)
        db.commit()

