def escape_xml(s: str) -> str:
    return (s or "").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace('"',"&quot;").replace("'","&apos;")

app = FastAPI(title=settings.app_name)

app.add_middleware(
    CORSMiddleware,
    allow_origins=settings.cors_origins,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.on_event("startup")
def on_startup():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        get_active_secret(db)
        ensure_admin(db)
        seed_demo(db)
    finally:
        db.close()

@app.get("/", include_in_schema=False)
def root():
    p = os.path.join(os.getcwd(),"index.html")
    if os.path.exists(p):
        return FileResponse(p, media_type="text/html; charset=utf-8")
    return {"status":"ok"}

@app.post("/api/v1/auth/login", response_model=AuthLoginResponse, status_code=status.HTTP_200_OK)
def auth_login(req: AuthLoginRequest, db: Session = Depends(get_db)):
    user = db.query(User).filter(User.email == req.email).first()
    if not user:
        raise HTTPException(status_code=401, detail="invalid credentials")
    if not password_verify(req.password, user.password_hash):
        raise HTTPException(status_code=401, detail="invalid credentials")
    token = create_access_token(db, str(user.id), {"email": user.email, "role": user.role, "name": user.name})
    return AuthLoginResponse(access_token=token, user={"id":user.id,"email":user.email,"name":user.name,"role":user.role})

@app.post("/api/v1/auth/rotate-keys", status_code=status.HTTP_204_NO_CONTENT)
def rotate_keys(_: Dict[str, Any] = Depends(auth_guard), db: Session = Depends(get_db)):
    rotate_secret(db)
    return

@app.get("/api/v1/metrics", response_model=MetricsResponse)
def metrics(_: Dict[str, Any] = Depends(auth_guard), db: Session = Depends(get_db)):
    today_start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    tx_today = db.query(Transaction).filter(Transaction.created_at >= today_start).all()
    total_transactions_today = len(tx_today)
    total_volume_today = sum([t.amount for t in tx_today]) if total_transactions_today>0 else Decimal("0")
    approved = len([t for t in tx_today if t.status=="approved"])
    success_rate = (approved/total_transactions_today) if total_transactions_today>0 else 0.0
    active_merchants = db.query(Merchant).filter(Merchant.status=="active").count()
    pending_settlements = 0
    average_transaction_value = (total_volume_today/total_transactions_today) if total_transactions_today>0 else Decimal("0")
    volume_trend = []
    transaction_trend = []
    for i in range(7):
        day = today_start - timedelta(days=(6-i))
        day_end = day + timedelta(days=1)
        tx = db.query(Transaction).filter(Transaction.created_at>=day, Transaction.created_at<day_end).all()
        volume_trend.append({"date": day.date().isoformat(), "amount": float(sum([t.amount for t in tx]) if tx else 0)})
        transaction_trend.append({"date": day.date().isoformat(), "count": len(tx)})
    return MetricsResponse(
        total_volume_today=total_volume_today,
        total_transactions_today=total_transactions_today,
        success_rate=success_rate,
        active_merchants=active_merchants,
        pending_settlements=pending_settlements,
        average_transaction_value=average_transaction_value,
        volume_trend=volume_trend,
        transaction_trend=transaction_trend
    )

@app.get("/api/v1/transactions")
def list_transactions(limit: int = Query(50, ge=1, le=500), _: Dict[str, Any] = Depends(auth_guard), db: Session = Depends(get_db)):
    rows = db.query(Transaction).order_by(Transaction.created_at.desc()).limit(limit).all()
    return [
        {
            "id": r.id,
            "merchant_id": r.merchant_id,
            "amount": float(r.amount),
            "currency": r.currency,
            "transaction_type": r.transaction_type,
            "status": r.status,
            "created_at": r.created_at.isoformat()+"Z"
        } for r in rows
    ]

