@app.post("/api/v1/sepa/credit-transfer")
def create_sepa_credit_transfer(request: SEPACreditTransferRequest, _: Dict[str, Any] = Depends(auth_guard)):
    if request.execution_date:
        try:
            _ = datetime.strptime(request.execution_date, "%Y-%m-%d").date()
        except Exception:
            raise HTTPException(status_code=400, detail="invalid execution_date")
    now = datetime.utcnow().strftime("%Y%m%d%H%M%S")
    lines = []
    lines.append('<?xml version="1.0" encoding="UTF-8"?>')
    lines.append('<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pain.001.001.03">')
    lines.append('<CstmrCdtTrfInitn>')
    lines.append('<GrpHdr>')
    lines.append(f'<MsgId>MSG{now}</MsgId>')
    lines.append(f'<CreDtTm>{datetime.utcnow().isoformat()}Z</CreDtTm>')
    lines.append('<NbOfTxs>'+str(len(request.transactions))+'</NbOfTxs>')
    total = sum([Decimal(str(t.get("amount",0))) for t in request.transactions])
    lines.append(f'<CtrlSum>{total:.2f}</CtrlSum>')
    lines.append('<InitgPty><Nm>'+escape_xml(request.debtor_name)+'</Nm></InitgPty>')
    lines.append('</GrpHdr>')
    lines.append('<PmtInf>')
    lines.append('<PmtInfId>PMT'+now+'</PmtInfId>')
    lines.append('<PmtMtd>TRF</PmtMtd>')
    lines.append('<NbOfTxs>'+str(len(request.transactions))+'</NbOfTxs>')
    lines.append(f'<CtrlSum>{total:.2f}</CtrlSum>')
    lines.append('<PmtTpInf><SvcLvl><Cd>SEPA</Cd></SvcLvl></PmtTpInf>')
    if request.execution_date:
        lines.append('<ReqdExctnDt>'+request.execution_date+'</ReqdExctnDt>')
    else:
        lines.append('<ReqdExctnDt>'+date.today().isoformat()+'</ReqdExctnDt>')
    lines.append('<Dbtr><Nm>'+escape_xml(request.debtor_name)+'</Nm></Dbtr>')
    lines.append('<DbtrAcct><Id><IBAN>'+escape_xml(request.debtor_iban)+'</IBAN></Id></DbtrAcct>')
    lines.append('<DbtrAgt><FinInstnId><BIC>'+escape_xml(request.debtor_bic)+'</BIC></FinInstnId></DbtrAgt>')
    lines.append('<ChrgBr>SLEV</ChrgBr>')
    for t in request.transactions:
        lines.append('<CdtTrfTxInf>')
        lines.append('<PmtId><EndToEndId>'+escape_xml(t.get("description","E2E"+now))+'</EndToEndId></PmtId>')
        lines.append('<Amt><InstdAmt Ccy="'+escape_xml(t.get("currency","EUR"))+'">'+f'{Decimal(str(t.get("amount",0))):.2f}'+'</InstdAmt></Amt>')
        lines.append('<Cdtr><Nm>'+escape_xml(t.get("creditor_name",""))+'</Nm></Cdtr>')
        lines.append('<CdtrAcct><Id><IBAN>'+escape_xml(t.get("creditor_iban",""))+'</IBAN></Id></CdtrAcct>')
        if t.get("creditor_bic"):
            lines.append('<CdtrAgt><FinInstnId><BIC>'+escape_xml(t.get("creditor_bic",""))+'</BIC></FinInstnId></CdtrAgt>')
        if t.get("description"):
            lines.append('<RmtInf><Ustrd>'+escape_xml(t.get("description",""))+'</Ustrd></RmtInf>')
        lines.append('</CdtTrfTxInf>')
    lines.append('</PmtInf>')
    lines.append('</CstmrCdtTrfInitn>')
    lines.append('</Document>')
    xml_content = "\n".join(lines)
    return {"xml": xml_content}

